87	type CheckoutRpcRow = { transaction_id: string; invoice_number: string; already_existed: boolean };
88	
89	export async function checkout(
90	  businessId: string,
91	  cashierId: string,
92	  items: CartItemInput[],
93	  paymentMethod: string,
94	  received: number | null,
95	  orderDisc: number,
96	  orderDiscType: DiscountType,
97	  customerId: string | null = null,
98	  selfOrderIds: string[] = [],
99	  // Dibuat sekali di browser per penjualan (crypto.randomUUID()) dan dikirim
100	  // ulang apa adanya kalau ini retry dari antrian offline — RPC memakainya
101	  // untuk mengenali retry yang mengulang penjualan yang sebenarnya sudah
102	  // sukses (respons sebelumnya tidak sempat sampai ke browser), supaya tidak
103	  // membuat transaksi duplikat. Lihat src/hooks/use-offline-sync.ts.
104	  clientRef: string | null = null,
105	): Promise<CheckoutResult> {
106	  if (items.length === 0) {
107	    return { success: false, error: "Keranjang masih kosong." };
108	  }
109	
110	  const supabase = await createClient();
111	  const { data, error } = await supabase
112	    .rpc("checkout_transaction", {
113	      p_business_id: businessId,
114	      p_cashier_id: cashierId,
115	      p_items: items.map((i) => ({
116	        product_id: i.productId,
117	        qty: i.qty,
118	        disc: i.disc,
119	        disc_type: i.discType,
120	        note: i.note ?? null,
121	      })),
122	      p_payment_method: paymentMethod,
123	      p_received: received,
124	      p_order_disc: orderDisc,
125	      p_order_disc_type: orderDiscType,
126	      p_customer_id: customerId,
127	      p_self_order_ids: selfOrderIds.length > 0 ? selfOrderIds : null,
128	      p_client_ref: clientRef,
129	    })
130	    .single();
131	
132	  if (error || !data) {
133	    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
134	  }
135	
136	  const result = data as CheckoutRpcRow;
137	  let printJobs: KitchenPrintJobPayload[] = [];
138	  let receiptPrintJobs: KitchenPrintJobPayload[] = [];
139	
140	  // Retry offline yang ternyata sudah pernah sukses sebelumnya — jangan catat
141	  // aktivitas/cetak dapur dua kali untuk penjualan yang sama.
142	  if (!result.already_existed) {
143	    const itemCount = items.reduce((sum, i) => sum + i.qty, 0);
144	
145	    // Tiga hal ini tidak saling bergantung — dulu dijalankan berurutan
146	    // (await satu-satu), menambah beberapa detik nyata ke waktu konfirmasi
147	    // pembayaran di jaringan mobile. Sekarang jalan bersamaan.
148	    const [, printJobsResult, receiptJobsResult] = await Promise.all([
149	      logActivity(
150	        supabase,
151	        businessId,
152	        "transaksi",
153	        "sukses",
154	        `Transaksi ${result.invoice_number}`,
155	        `${itemCount} item · ${paymentMethod}`,
156	      ),
157	      buildKitchenPrintJobsForItems(
158	        supabase,
159	        businessId,
160	        "Kasir",
161	        result.invoice_number,
162	        items.map((i) => ({ productId: i.productId, qty: i.qty, note: i.note })),
163	      ),
164	      buildReceiptPrintJobsForTransaction(supabase, businessId, result.transaction_id),
165	    ]);
166	    printJobs = printJobsResult;
167	    receiptPrintJobs = receiptJobsResult;
168	  }
169	
170	  return {
171	    success: true,
172	    invoiceNumber: result.invoice_number,
173	    transactionId: result.transaction_id,
174	    printJobs,
175	    receiptPrintJobs,
176	  };
177	}
