214	async function buildKitchenPrintJobsForItems(
215	  supabase: Awaited<ReturnType<typeof createClient>>,
216	  businessId: string,
217	  source: string,
218	  label: string,
219	  items: { productId: string; qty: number; note?: string | null }[],
220	): Promise<KitchenPrintJobPayload[]> {
221	  const productIds = Array.from(new Set(items.map((i) => i.productId)));
222	  const { data: products } = await supabase
223	    .from("products")
224	    .select("id, name, category")
225	    .in("id", productIds);
226	  const productMap = new Map((products ?? []).map((p) => [p.id, p]));
227	
228	  return buildKitchenPrintJobs(supabase, businessId, {
229	    source,
230	    label,
231	    items: items.map((i) => ({
232	      name: productMap.get(i.productId)?.name ?? "Item",
233	      category: productMap.get(i.productId)?.category ?? null,
234	      qty: i.qty,
235	      note: i.note,
236	    })),
237	  }).catch(() => []);
238	}
