359	export async function closeShift(
360	  businessId: string,
361	  shiftId: string,
362	  closingCash: number,
363	  closeNotes: string,
364	): Promise<CloseShiftResult> {
365	  const supabase = await createClient();
366	  const { data, error } = await supabase
367	    .rpc("close_shift", {
368	      p_shift_id: shiftId,
369	      p_closing_cash: closingCash,
370	      p_close_notes: closeNotes || null,
371	    })
372	    .single();
373	
374	  if (error || !data) {
375	    return { success: false, error: error?.message ?? "Gagal menutup shift." };
