438	export async function saveOpenBill(
439	  businessId: string,
440	  billId: string | null,
441	  label: string,
442	  items: OpenBillItemInput[],
443	): Promise<SaveOpenBillResult> {
444	  const trimmed = label.trim();
445	  if (!trimmed) {
446	    return { success: false, error: "Nama bon wajib diisi." };
447	  }
448	  if (items.length === 0) {
449	    return { success: false, error: "Keranjang masih kosong." };
450	  }
451	
452	  const supabase = await createClient();
453	
454	  if (billId) {
455	    const { error } = await supabase
456	      .from("open_bills")
457	      .update({ label: trimmed, items, updated_at: new Date().toISOString() })
458	      .eq("id", billId)
459	      .eq("business_id", businessId);
460	    if (error) {
461	      return { success: false, error: error.message };
462	    }
463	    revalidatePath(`/business/${businessId}/pos`);
464	    return { success: true, billId };
465	  }
466	
467	  const { data, error } = await supabase
468	    .from("open_bills")
469	    .insert({ business_id: businessId, label: trimmed, items })
470	    .select("id")
471	    .single();
472	
473	  if (error || !data) {
474	    return { success: false, error: error?.message ?? "Gagal menyimpan bon." };
475	  }
476	
477	  await logActivity(
478	    supabase,
479	    businessId,
480	    "transaksi",
481	    "info",
482	    `Open Bill dibuat: ${trimmed}`,
483	    `${items.length} jenis item`,
484	  );
485	  revalidatePath(`/business/${businessId}/pos`);
486	  return { success: true, billId: data.id };
487	}
