532	// Sumber tunggal data katalog POS (produk/open bill/customer/metode bayar
533	// custom) — dipakai baik untuk render server pertama kali (pos/page.tsx)
534	// maupun refresh di background dari client (pos-screen.tsx, lihat
535	// pos-cache.ts). Sengaja tidak termasuk self_orders — itu sudah punya jalur
536	// polling sendiri (getSelfOrders di bawah).
537	export async function getPosCatalog(businessId: string): Promise<PosCatalog> {
538	  const supabase = await createClient();
539	
540	  const [{ data: products }, { data: openBillRows }, { data: customers }, { data: customPaymentMethodRows }, { data: discountRuleRows }] =
541	    await Promise.all([
542	      supabase
543	        .from("products")
544	        .select("id, name, category, price, cost, stock, emoji, barcode, sku, variant_label")
545	        .eq("business_id", businessId)
546	        .is("deleted_at", null)
547	        .order("name", { ascending: true }),
548	      supabase
549	        .from("open_bills")
550	        .select("id, label, items, updated_at")
551	        .eq("business_id", businessId)
552	        .order("updated_at", { ascending: false }),
553	      supabase
554	        .from("customers")
555	        .select("id, name, phone")
556	        .eq("business_id", businessId)
557	        .is("deleted_at", null)
558	        .order("name", { ascending: true }),
559	      supabase
560	        .from("custom_payment_methods")
561	        .select("name")
562	        .eq("business_id", businessId)
563	        .order("name", { ascending: true }),
564	      supabase
565	        .from("discount_rules")
566	        .select("id, type, product_id, name, value, value_type, active, valid_from, valid_until")
567	        .eq("business_id", businessId),
568	    ]);
569	
570	  return {
571	    products: (products ?? []) as PosProduct[],
572	    openBills: (openBillRows ?? []) as unknown as PosOpenBill[],
573	    customers: customers ?? [],
574	    customPaymentMethods: (customPaymentMethodRows ?? []).map((m) => m.name),
575	    discountRules: (discountRuleRows ?? []) as DiscountRule[],
576	  };
577	}
