579	export type SelfOrderPayload = {
580	  id: string;
581	  status: "baru" | "diproses";
582	  createdAt: string;
583	  tableName: string;
584	  items: { productId: string | null; name: string; qty: number; price: number; note: string | null }[];
585	};
