587	// Dipakai oleh polling badge order masuk di pos-screen.tsx — dulu polling
588	// itu panggil router.refresh() tiap 15 detik, yang re-render SELURUH
589	// halaman POS (produk, open bill, customer, dst ikut di-fetch ulang).
590	// Action ini cuma ambil self_orders sendirian, jauh lebih ringan.
591	export async function getSelfOrders(businessId: string): Promise<SelfOrderPayload[]> {
592	  const supabase = await createClient();
593	  const { data } = await supabase
594	    .from("self_orders")
595	    .select(
596	      "id, status, created_at, tables(name), self_order_items(product_id, name, qty, price, note)",
597	    )
598	    .eq("business_id", businessId)
599	    .neq("status", "selesai")
600	    .order("created_at", { ascending: true });
601	
602	  return (
603	    data as unknown as {
604	      id: string;
605	      status: "baru" | "diproses";
606	      created_at: string;
607	      tables: { name: string } | null;
608	      self_order_items: { product_id: string | null; name: string; qty: number; price: number; note: string | null }[];
609	    }[]
610	    ?? []
611	  ).map((o) => ({
612	    id: o.id,
613	    status: o.status,
614	    createdAt: o.created_at,
615	    tableName: o.tables?.name ?? "Meja terhapus",
616	    items: o.self_order_items.map((i) => ({
617	      productId: i.product_id,
618	      name: i.name,
619	      qty: i.qty,
620	      price: i.price,
621	      note: i.note,
622	    })),
623	  }));
624	}
