626	export async function updateSelfOrderStatus(
627	  businessId: string,
628	  orderId: string,
629	  status: "diproses" | "selesai",
630	): Promise<{ success: boolean; error?: string; printJobs?: KitchenPrintJobPayload[] }> {
631	  const supabase = await createClient();
632	  const { data, error } = await supabase
633	    .from("self_orders")
