1	export type DiscountType = "pct" | "amt";
2	
3	export type CheckoutLineItem = {
4	  price: number;
5	  qty: number;
6	  disc: number;
7	  discType: DiscountType;
8	};
9	
10	export function itemDiscAmount(item: CheckoutLineItem): number {
11	  const lineGross = item.price * item.qty;
12	  return item.discType === "pct"
13	    ? Math.round((lineGross * item.disc) / 100)
14	    : Math.min(item.disc * item.qty, lineGross);
15	}
16	
17	export type CheckoutTotals = {
18	  subtotalRaw: number;
19	  totalItemDisc: number;
20	  afterItemDisc: number;
21	  orderDiscAmt: number;
22	  subtotal: number;
23	  serviceAmt: number;
24	  taxAmt: number;
25	  total: number;
26	};
27	
28	// Urutan hitung mengikuti aplikasi lama: diskon item -> diskon order -> layanan
29	// dari subtotal -> PPN dari (subtotal + layanan). Server RPC menghitung ulang
30	// angka final secara independen; ini dipakai untuk tampilan kasir.
31	export function calculateCheckoutTotals(params: {
32	  items: CheckoutLineItem[];
33	  orderDisc: number;
34	  orderDiscType: DiscountType;
35	  serviceRate: number;
36	  taxRate: number;
37	}): CheckoutTotals {
38	  const { items, orderDisc, orderDiscType, serviceRate, taxRate } = params;
39	
40	  const subtotalRaw = items.reduce((sum, item) => sum + item.price * item.qty, 0);
41	  const totalItemDisc = items.reduce((sum, item) => sum + itemDiscAmount(item), 0);
42	  const afterItemDisc = subtotalRaw - totalItemDisc;
43	  const orderDiscAmt =
44	    orderDiscType === "pct"
45	      ? Math.round((afterItemDisc * orderDisc) / 100)
46	      : Math.min(orderDisc, afterItemDisc);
47	  const subtotal = afterItemDisc - orderDiscAmt;
48	  const serviceAmt = Math.round((subtotal * serviceRate) / 100);
49	  const taxAmt = Math.round(((subtotal + serviceAmt) * taxRate) / 100);
50	  const total = subtotal + serviceAmt + taxAmt;
51	
52	  return {
53	    subtotalRaw,
54	    totalItemDisc,
55	    afterItemDisc,
56	    orderDiscAmt,
57	    subtotal,
58	    serviceAmt,
59	    taxAmt,
60	    total,
61	  };
62	}
