1	// Wrapper tipis di atas IndexedDB bawaan browser — dipakai untuk menyimpan
2	// antrian penjualan yang gagal disinkronkan karena jaringan putus di
3	// pos-screen.tsx / ticket-pos-screen.tsx, cache katalog POS (sejak v2) di
4	// pos-cache.ts untuk render instan di pembukaan berikutnya, dan (sejak v3)
5	// antrian cetak dapur/bar/struk yang gagal terkirim di print-queue.ts.
6	// Tidak ada dependency baru; hanya jalan di client (semua pemanggil harus
7	// mengecek `typeof window !== "undefined"` / dipanggil dari komponen
8	// "use client").
9	
10	const DB_NAME = "kasirku-offline";
11	const DB_VERSION = 3;
12	const STORE_NAME = "pending_sales";
13	const POS_CACHE_STORE = "pos_cache";
14	const PENDING_PRINTS_STORE = "pending_prints";
15	
16	function openDb(): Promise<IDBDatabase> {
17	  return new Promise((resolve, reject) => {
18	    const request = indexedDB.open(DB_NAME, DB_VERSION);
19	
20	    request.onupgradeneeded = () => {
21	      const db = request.result;
22	      if (!db.objectStoreNames.contains(STORE_NAME)) {
23	        const store = db.createObjectStore(STORE_NAME, { keyPath: "clientRef" });
24	        store.createIndex("by-business", "businessId", { unique: false });
25	      }
26	      if (!db.objectStoreNames.contains(POS_CACHE_STORE)) {
27	        db.createObjectStore(POS_CACHE_STORE, { keyPath: "businessId" });
28	      }
29	      if (!db.objectStoreNames.contains(PENDING_PRINTS_STORE)) {
30	        const store = db.createObjectStore(PENDING_PRINTS_STORE, { keyPath: "id" });
31	        store.createIndex("by-business", "businessId", { unique: false });
32	      }
33	    };
34	
35	    request.onsuccess = () => resolve(request.result);
36	    request.onerror = () => reject(request.error);
37	  });
38	}
39	
40	export async function idbPut<T>(record: T): Promise<void> {
41	  const db = await openDb();
