1	"use client";
2	
3	import { Capacitor } from "@capacitor/core";
4	import { printViaAgent, type PrintAgentResult } from "./print-agent-client";
5	import KitchenPrinter from "./kitchen-printer-plugin";
6	import type { KitchenPrintJobPayload } from "./kitchen-print";
7	import { logKitchenPrintFailures, logPrintQueueRecovered } from "@/app/business/[businessId]/pos/actions";
8	import {
9	  enqueuePrintJob,
10	  listPendingPrints,
11	  markPrintAttempt,
12	  markPrintSynced,
13	} from "@/lib/print-queue";
14	
15	// Android app (android-app/) supplies KitchenPrinter natively — the browser
16	// on the cashier's own tablet is on the shop's LAN (or physically holding
17	// it, for Bluetooth), so it can dial the printer directly, no print-agent PC
18	// needed. Plain browsers keep using the print-agent HTTP relay for LAN jobs
19	// (untouched); they have no way to reach a bluetooth job at all.
20	async function dispatchOne(job: KitchenPrintJobPayload): Promise<PrintAgentResult> {
21	  if (Capacitor.isNativePlatform()) {
22	    const result =
23	      job.connectionType === "lan"
24	        ? await (() => {
25	            const [ip, portStr] = job.address.split(":");
26	            const port = portStr ? Number(portStr) : 9100;
27	            return KitchenPrinter.printLan({ ip, port, bytesBase64: job.bytesBase64 });
28	          })()
29	        : await KitchenPrinter.printBluetooth({ address: job.address, bytesBase64: job.bytesBase64 });
30	    return result.ok
31	      ? { ok: true }
32	      : { ok: false, reason: "printer_unreachable", error: result.error ?? "unknown_error" };
33	  }
34	  if (job.connectionType === "bluetooth") {
35	    return { ok: false, reason: "printer_unreachable", error: "unsupported_on_web" };
36	  }
37	  return printViaAgent(job.address, job.bytesBase64);
38	}
39	
40	export type DispatchedPrintResult = { job: KitchenPrintJobPayload; result: PrintAgentResult };
41	
42	// Fire-and-forget from the checkout/order-status callers' point of view — a
43	// failed kitchen print must never block or fail the sale/order that
44	// triggered it (same principle the old server-side dispatchKitchenPrint
45	// followed), so they just `void` this call. The return value exists for
46	// callers that DO want to know per-job success/failure inline (e.g. a
47	// "Tes Cetak" button) — existing fire-and-forget callers are unaffected.
48	export async function dispatchPrintJobs(
49	  businessId: string,
50	  jobs: KitchenPrintJobPayload[],
51	): Promise<DispatchedPrintResult[]> {
52	  if (jobs.length === 0) return [];
53	
54	  const results = await Promise.all(
55	    jobs.map(async (job) => ({ job, result: await dispatchOne(job) })),
56	  );
57	
58	  const failed = results.filter((r) => !r.result.ok);
59	  if (failed.length > 0) {
60	    await logKitchenPrintFailures(
61	      businessId,
62	      failed.map(({ job, result }) => ({
63	        printer: job.printerName,
64	        error: result.ok ? "" : result.error,
65	      })),
66	    ).catch(() => {});
67	
68	    // Printer mati sesaat itu wajar (kertas habis, belum dinyalain) — jangan
69	    // biarkan tiket/struk itu hilang begitu saja. Simpan ke antrian lokal,
70	    // usePrintRetry (pos-screen.tsx) yang akan coba lagi berkala sampai
71	    // berhasil atau mentok MAX_ATTEMPTS.
72	    await Promise.all(failed.map(({ job }) => enqueuePrintJob(businessId, job))).catch(() => {});
73	  }
74	
75	  return results;
76	}
77	
78	// Dipanggil berkala oleh usePrintRetry — TIDAK memanggil
79	// logKitchenPrintFailures di setiap percobaan (itu akan membanjiri activity
80	// log tiap ~20 detik); hanya mencatat sekali saat sebuah job akhirnya
81	// berhasil setelah sempat gagal.
82	export async function retryPendingPrintJobs(businessId: string): Promise<void> {
83	  const pending = await listPendingPrints(businessId);
84	  for (const p of pending.filter((p) => p.status === "pending")) {
85	    const result = await dispatchOne(p.job);
86	    if (result.ok) {
87	      await markPrintSynced(p.id);
88	      await logPrintQueueRecovered(businessId, p.job.printerName).catch(() => {});
89	    } else {
90	      await markPrintAttempt(p, result.error);
91	    }
92	  }
93	}
