95	// Receipt jobs go out first and are awaited before the kitchen jobs start —
96	// two reasons: the cashier's receipt printer is often the same physical
97	// device as a kitchen station (Bluetooth sockets don't handle concurrent
98	// jobs well), and the customer copy is the priority print, not the kitchen
99	// ticket.
100	export async function dispatchReceiptThenKitchenJobs(
101	  businessId: string,
102	  receiptJobs: KitchenPrintJobPayload[],
103	  kitchenJobs: KitchenPrintJobPayload[],
104	) {
105	  await dispatchPrintJobs(businessId, receiptJobs);
106	  await dispatchPrintJobs(businessId, kitchenJobs);
107	}
