1	// Minimal ESC/POS command builder for thermal kitchen-ticket printing.
2	// Text is sent as latin1 bytes (matches the default CP437-ish codepage on
3	// most cheap 58/80mm thermal printers for the plain-ASCII characters we use).
4	
5	const ESC = 0x1b;
6	const GS = 0x1d;
7	
8	export type KitchenTicketItem = {
9	  name: string;
10	  qty: number;
11	  note?: string | null;
12	};
13	
14	export type KitchenTicketInput = {
15	  station: string;
16	  source: string;
17	  label: string;
18	  items: KitchenTicketItem[];
19	};
20	
21	function formatQty(qty: number): string {
22	  return Number.isInteger(qty) ? String(qty) : qty.toFixed(2);
23	}
24	
25	export function buildKitchenTicket(input: KitchenTicketInput): Buffer {
26	  const chunks: Buffer[] = [];
27	  const push = (bytes: number[]) => chunks.push(Buffer.from(bytes));
28	  const text = (s: string) => chunks.push(Buffer.from(`${s}\n`, "latin1"));
29	
30	  push([ESC, 0x40]); // initialize
31	
32	  push([ESC, 0x61, 0x01]); // center align
33	  push([GS, 0x21, 0x11]); // double width + height
34	  text(input.station.toUpperCase());
35	  push([GS, 0x21, 0x00]); // back to normal size
36	
37	  push([ESC, 0x61, 0x00]); // left align
38	  text(`${input.source} - ${input.label}`);
39	  text(new Date().toLocaleString("id-ID"));
40	  text("--------------------------------");
41	
42	  for (const item of input.items) {
43	    push([ESC, 0x45, 0x01]); // bold on
44	    text(`${formatQty(item.qty)}x ${item.name}`);
45	    push([ESC, 0x45, 0x00]); // bold off
46	    if (item.note) {
47	      text(`   Catatan: ${item.note}`);
48	    }
49	  }
50	
51	  text("");
52	  text("");
53	  push([GS, 0x56, 0x42, 0x00]); // partial cut with feed
54	
55	  return Buffer.concat(chunks);
56	}
57	
58	// 32 columns matches Font A on the 58mm thermal printers this app targets
59	// (RPP02N and similar) — used to right-align prices/totals in plain text
60	// since ESC/POS has no flex layout.
61	const RECEIPT_WIDTH = 32;
62	
63	function padLine(left: string, right: string, width = RECEIPT_WIDTH): string {
64	  const space = Math.max(width - left.length - right.length, 1);
65	  return left + " ".repeat(space) + right;
66	}
67	
68	function truncate(s: string, width = RECEIPT_WIDTH): string {
69	  return s.length > width ? s.slice(0, width) : s;
70	}
71	
72	export type ReceiptItem = {
73	  name: string;
74	  qty: number;
75	  price: number;
76	};
77	
78	export type ReceiptPayment = {
79	  method: string;
80	  amount: number;
81	  received: number | null;
82	  change: number | null;
83	};
84	
85	export type ReceiptTicketInput = {
86	  businessName: string;
87	  invoiceNumber: string;
88	  date: string;
89	  cashierName: string;
90	  voided: boolean;
91	  items: ReceiptItem[];
92	  subtotal: number;
93	  itemDiscount: number;
94	  orderDiscount: number;
95	  service: number;
96	  tax: number;
97	  total: number;
98	  payments: ReceiptPayment[];
99	};
100	
101	function formatRp(value: number): string {
102	  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
103	}
104	
105	// Full priced customer receipt (struk kasir) — distinct from
106	// buildKitchenTicket, which deliberately omits prices for the kitchen/bar
107	// copy. Sent through the same native LAN/Bluetooth plugin as kitchen
108	// tickets, since Android's OS-level print framework generally can't drive
109	// cheap ESC/POS thermal printers (see dispatch-print-jobs.ts).
110	export function buildReceiptTicket(input: ReceiptTicketInput): Buffer {
111	  const chunks: Buffer[] = [];
112	  const push = (bytes: number[]) => chunks.push(Buffer.from(bytes));
113	  const text = (s: string) => chunks.push(Buffer.from(`${s}\n`, "latin1"));
114	  const divider = () => text("-".repeat(RECEIPT_WIDTH));
115	
116	  push([ESC, 0x40]); // initialize
117	
118	  push([ESC, 0x61, 0x01]); // center align
119	  text(input.businessName.toUpperCase());
120	  if (input.voided) {
121	    push([ESC, 0x45, 0x01]);
122	    text("*** DIBATALKAN ***");
123	    push([ESC, 0x45, 0x00]);
124	  }
125	  push([ESC, 0x61, 0x00]); // left align
126	
127	  divider();
128	  text(padLine("No.", input.invoiceNumber));
129	  text(padLine("Tanggal", input.date));
130	  text(padLine("Kasir", input.cashierName));
131	
132	  divider();
133	  for (const item of input.items) {
134	    text(truncate(item.name));
135	    text(padLine(`  ${formatQty(item.qty)}x${formatRp(item.price)}`, formatRp(item.price * item.qty)));
136	  }
137	
138	  divider();
139	  text(padLine("Subtotal", formatRp(input.subtotal)));
140	  if (input.itemDiscount > 0) text(padLine("Diskon item", `-${formatRp(input.itemDiscount)}`));
141	  if (input.orderDiscount > 0) text(padLine("Diskon order", `-${formatRp(input.orderDiscount)}`));
142	  if (input.service > 0) text(padLine("Layanan", formatRp(input.service)));
143	  if (input.tax > 0) text(padLine("PPN", formatRp(input.tax)));
144	  push([ESC, 0x45, 0x01]);
145	  text(padLine("TOTAL", formatRp(input.total)));
146	  push([ESC, 0x45, 0x00]);
147	
148	  divider();
149	  for (const p of input.payments) {
150	    text(padLine(p.method, formatRp(p.amount)));
151	    if (p.received !== null) text(padLine("Diterima", formatRp(p.received)));
152	    if (p.change !== null && p.change > 0) text(padLine("Kembalian", formatRp(p.change)));
153	  }
154	
155	  push([ESC, 0x61, 0x01]); // center align
156	  text("");
157	  text("Terima kasih!");
158	  text("");
159	  text("");
160	  push([GS, 0x56, 0x42, 0x00]); // partial cut with feed
161	
162	  return Buffer.concat(chunks);
163	}
