26	export async function enqueuePrintJob(
27	  businessId: string,
28	  job: KitchenPrintJobPayload,
29	): Promise<void> {
30	  const pending: PendingPrintJob = {
31	    id: crypto.randomUUID(),
32	    businessId,
33	    createdAt: new Date().toISOString(),
34	    attempts: 0,
35	    status: "pending",
36	    job,
37	  };
