143	function parseTicketCategoryFields(formData: FormData): ParsedTicketCategoryFields {
144	  const name = (formData.get("name") as string)?.trim();
145	  const priceWeekday = Number(formData.get("priceWeekday"));
146	  const priceHoliday = Number(formData.get("priceHoliday"));
147	  const memberPrice = Number(formData.get("memberPrice"));
148	  const groupMinQtyRaw = (formData.get("groupMinQty") as string)?.trim();
149	  const groupPriceRaw = (formData.get("groupPrice") as string)?.trim();
150	
151	  if (!name) return { error: "Nama kategori wajib diisi." };
152	  if (Number.isNaN(priceWeekday) || priceWeekday < 0) {
153	    return { error: "Harga hari kerja harus angka dan tidak boleh negatif." };
154	  }
155	  if (Number.isNaN(priceHoliday) || priceHoliday < 0) {
156	    return { error: "Harga hari libur harus angka dan tidak boleh negatif." };
157	  }
158	  if (Number.isNaN(memberPrice) || memberPrice < 0) {
159	    return { error: "Harga member harus angka dan tidak boleh negatif." };
160	  }
161	
162	  const groupMinQty = groupMinQtyRaw ? Number(groupMinQtyRaw) : 0;
163	  if (Number.isNaN(groupMinQty) || groupMinQty < 0) {
164	    return { error: "Minimal qty rombongan harus angka dan tidak boleh negatif." };
165	  }
166	  const groupPrice = groupPriceRaw ? Number(groupPriceRaw) : null;
167	  if (groupPrice !== null && (Number.isNaN(groupPrice) || groupPrice < 0)) {
168	    return { error: "Harga rombongan harus angka dan tidak boleh negatif." };
169	  }
170	
171	  return { error: null, name, priceWeekday, priceHoliday, memberPrice, groupMinQty, groupPrice };
