1	// Membungkus sebuah promise dengan batas waktu tanpa membatalkan promise
2	// aslinya — kalau promise asli belakangan tetap selesai (sukses atau
3	// gagal) setelah timeout duluan yang menang, itu diam-diam diabaikan
4	// (bukan unhandled rejection) karena promise hanya bisa settle sekali.
5	// Dipakai pos-screen.tsx / ticket-pos-screen.tsx untuk mendeteksi checkout
6	// yang macet karena jaringan tanpa membuat kasir menunggu tanpa batas.
7	export function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
8	  return new Promise<T>((resolve, reject) => {
9	    const timer = setTimeout(() => reject(new Error("timeout")), ms);
10	    promise.then(
11	      (value) => {
12	        clearTimeout(timer);
13	        resolve(value);
14	      },
15	      (err) => {
16	        clearTimeout(timer);
17	        reject(err);
18	      },
19	    );
20	  });
21	}
