3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { retryPendingPrintJobs } from "@/lib/dispatch-print-jobs";
5	import { discardPendingPrint, listPendingPrints, type PendingPrintJob } from "@/lib/print-queue";
6	
7	const RETRY_INTERVAL_MS = 20000;
8	
9	// Dipakai di pos-screen.tsx. Printer dapur/bar yang mati saat sebuah tiket
10	// coba dikirim (lihat dispatch-print-jobs.ts) masuk ke antrian lokal —
11	// hook ini yang coba kirim ulang berkala sampai berhasil atau mentok
12	// MAX_ATTEMPTS (lihat print-queue.ts), sama polanya dengan useOfflineSync
13	// untuk penjualan offline.
14	export function usePrintRetry(businessId: string) {
15	  const [pending, setPending] = useState<PendingPrintJob[]>([]);
16	  const retryingRef = useRef(false);
17	
18	  const refresh = useCallback(async () => {
19	    const rows = await listPendingPrints(businessId);
20	    setPending(rows);
21	    return rows;
22	  }, [businessId]);
23	
24	  const retryNow = useCallback(async () => {
25	    if (retryingRef.current) return;
26	    retryingRef.current = true;
27	    try {
28	      await retryPendingPrintJobs(businessId);
29	    } finally {
30	      retryingRef.current = false;
31	      await refresh();
32	    }
33	  }, [businessId, refresh]);
34	
35	  const discard = useCallback(
36	    async (id: string) => {
37	      await discardPendingPrint(id);
38	      await refresh();
39	    },
40	    [refresh],
41	  );
42	
43	  useEffect(() => {
44	    void refresh();
45	  }, [refresh]);
46	
47	  useEffect(() => {
48	    function handleOnline() {
49	      void retryNow();
50	    }
51	    window.addEventListener("online", handleOnline);
52	    return () => window.removeEventListener("online", handleOnline);
53	  }, [retryNow]);
54	
55	  useEffect(() => {
56	    const interval = setInterval(() => {
57	      if (pending.some((p) => p.status === "pending")) void retryNow();
58	    }, RETRY_INTERVAL_MS);
59	    return () => clearInterval(interval);
60	  }, [pending, retryNow]);
61	
62	  return { pending, retryNow, discard };
63	}
